// Category A — behavior borrowed from react-aria-components, look (.sd-button) owned in src.
// This is the “reference component” for the entire DS. Every subsequent component follows this contract.
// (Full contract: docs/rules/component-contract.md)
import {
  Button as AriaButton,
  Provider,
  Text,
  TextContext,
} from "react-aria-components";
import type { ButtonProps as AriaButtonProps } from "react-aria-components";
import { Children, Fragment, cloneElement, isValidElement } from "react";
import type { CSSProperties, Ref } from "react";
import { Spinner } from "./Spinner";
import { roleSize, type ControlSize } from "./controlSize";
import "./Button.css";

type ButtonVariant = "primary" | "secondary" | "tonal" | "strong" | "outline" | "destructive" | "ghost" | "surface";
type ButtonSize = ControlSize;
type ButtonOrientation = "horizontal" | "vertical";
type ButtonShape = "rectangle" | "circle";

/** Common Button props — axes independent of isIconOnly (variant · size · look). */
export interface ButtonBaseProps extends Omit<AriaButtonProps, "className"> {
  /**
   * Visual variant: emphasis, never a palette role. `secondary` is the ladder's non-primary rung,
   * and the BRAND decides how it draws (a neutral fill, or a transparent box with an edge;
   * ADR-0045), so a call site never picks the look. `outline` is the media look, a frosted edge
   * over a photo. `surface` paints the page's own surface with the page's ink, for a Button sitting
   * on a canvas that is not a surface (a tinted row, a grey canvas, a wallpaper), where `secondary`
   * would sink and `outline` would take the tint. `tonal` is medium emphasis on the brand's tint (another
   * path that still advances the task); `strong` is a solid non-brand action co-equal with `primary`.
   * `provider` hands the action to a third party (signing in, sharing or subscribing through another
   * service) and draws it in that party's own colour, which the caller supplies with
   * `providerColor` and `providerForeground`; the design system ships no third party's colour or
   * mark. The party's mark goes in `children` beside the label in `<Text>`, as any leading icon does.
   *
   * @default "primary"
   */
  variant?: ButtonVariant | "provider";
  /**
   * Size axis, one rung of the control-height ladder per size: height, padding, icon and corner
   * follow it, and the label's type role follows its nearest of small, medium and large.
   *
   * @default "medium"
   */
  size?: ButtonSize;
}

/**
 * Button props.
 *
 * TWO square, text-less modes, and they are mutually exclusive. Both leave the `size` axis
 * untouched and only make the shape square, so combine them with a size as in
 * `size="large" isIconOnly`:
 *
 * - `isIconOnly` — exactly one icon as children (for example, `<Trash aria-hidden size="1em" />`).
 *   The glyph reads one rung UP the icon scale, because it carries the button alone.
 * - `isMediaOnly` — an image, thumbnail or other media as children. The button clips it to its own
 *   radius, and no glyph sizing applies: media brings its own dimensions. Reach for this instead of
 *   sizing the button from the outside — a consumer that sets the box geometry on the button is
 *   restyling a Component from a Block, which `block-contract.md` §3 forbids.
 *
 * Because neither mode has visible text, an accessible name is **required at the type level** —
 * one of `aria-label` or `aria-labelledby` must be passed for it to compile. Text buttons do not
 * have this constraint because children provides the label.
 * (The contract's only discriminated-union props — see component-contract.md §2.)
 *
 * `orientation="vertical"` sets a round plate holding the icon over a caption, for a row of peer
 * quick actions (share · expand · leave). Pass one `aria-hidden` icon and the caption in `<Text>`;
 * the caption is the button's visible, accessible name and the whole column is the press target.
 * It needs visible text, so the square modes cannot take it.
 *
 * `shape="circle"` rounds the square fully, for a floating or compact round icon button. It is
 * valid only with `isIconOnly`, enforced by the union below: a worded box would turn into a capsule
 * and media clips to its own quarter-capped corner, so every other branch accepts only the default
 * `"rectangle"`, the same way the square modes accept only `orientation="horizontal"`.
 */
export type ButtonProps = ButtonBaseProps &
  (
    | {
        isIconOnly?: false;
        isMediaOnly?: false;
        /**
         * Presentation: `vertical` sets a round plate over a caption (see above).
         *
         * @default "horizontal"
         */
        orientation?: ButtonOrientation;
        /**
         * Box shape. `circle` is valid only with `isIconOnly` (see above).
         *
         * @default "rectangle"
         */
        shape?: "rectangle";
      }
    | { isIconOnly: true; isMediaOnly?: false; orientation?: "horizontal"; shape?: ButtonShape; "aria-label": string }
    | { isIconOnly: true; isMediaOnly?: false; orientation?: "horizontal"; shape?: ButtonShape; "aria-labelledby": string }
    | { isIconOnly?: false; isMediaOnly: true; orientation?: "horizontal"; shape?: "rectangle"; "aria-label": string }
    | { isIconOnly?: false; isMediaOnly: true; orientation?: "horizontal"; shape?: "rectangle"; "aria-labelledby": string }
  ) &
  (
    | { variant?: ButtonVariant; providerColor?: undefined; providerForeground?: undefined }
    | {
        variant: "provider";
        /**
         * The third party's fill, as a CSS colour. It is theirs, so it is the same in every theme
         * and brand, and the caller checks it against the page in each theme it ships: a fill that
         * matches one theme's surface leaves the label alone to show the button.
         * Required with `variant="provider"`.
         */
        providerColor: string;
        /**
         * The label and mark ink on `providerColor`, as a CSS colour. The caller owns this pair
         * clearing 4.5:1 (WCAG 1.4.3); the design system cannot measure a colour it never sees.
         */
        providerForeground: string;
      }
  ) & {
    /** Additional class (optional). sd-button is always preserved. */
    className?: string;
    /** Forwarded to the underlying <button> DOM node. */
    ref?: Ref<HTMLButtonElement>;
  };

/**
 * Whether children consists only of renderable **text**. Only then does Button automatically wrap
 * the label in `<Text>` (§4 text slot). `Children.toArray` filters null/boolean/empty fragments, so
 * it is enough to check whether every remaining fragment is a string/number. Empty children is
 * false because there is nothing to wrap.
 */
/** Children flattened through fragments, so `<><Icon /><Text>…</Text></>` yields its two parts. */
function flatten(content: React.ReactNode): React.ReactNode[] {
  return Children.toArray(content).flatMap((p) =>
    isValidElement<{ children?: React.ReactNode }>(p) && p.type === Fragment
      ? flatten(p.props.children)
      : [p],
  );
}

function isTextOnly(content: React.ReactNode): boolean {
  const parts = Children.toArray(content);
  return (
    parts.length > 0 &&
    parts.every((p) => typeof p === "string" || typeof p === "number")
  );
}

export function Button({
  variant = "primary",
  size = "medium",
  isIconOnly = false,
  isMediaOnly = false,
  orientation = "horizontal",
  shape = "rectangle",
  providerColor,
  providerForeground,
  children,
  className,
  style,
  ...props
}: ButtonProps) {
  // A provider's pair rides in as two local properties the variant rule reads (MessagePreview's
  // shape): they are the caller's values, not tokens, so they never reach tokens.css.
  const providerStyle = providerColor
    ? ({ "--sd-button-provider-background": providerColor, "--sd-button-provider-foreground": providerForeground } as CSSProperties)
    : undefined;
  return (
    <AriaButton
      {...props}
      style={
        providerStyle
          ? (renderProps) => ({ ...providerStyle, ...(typeof style === "function" ? style(renderProps) : style) })
          : style
      }
      data-variant={variant}
      data-size={size}
      data-icon-only={isIconOnly || undefined}
      data-media-only={isMediaOnly || undefined}
      data-orientation={orientation}
      data-shape={isIconOnly ? shape : undefined}
      className={
        // size-variant text: apply the size-matched label type role (sd-type-label-<size>)
        // — label/{small,medium,large} differ only in font-size, so this carries the correct
        // per-size typography with no redundant per-size font-size Cmp token (contract §7). The
        // type roles keep three sizes, so x-small and x-large take their neighbour's (roleSize).
        className
          ? `sd-button sd-type-label-${roleSize(size)} ${className}`
          : `sd-button sd-type-label-${roleSize(size)}`
      }
    >
      {(renderProps) => {
        const content =
          typeof children === "function" ? children(renderProps) : children;
        if (orientation === "vertical") {
          // Flatten fragments, then normalise a text-only label into one <Text>, so a bare "Share"
          // (fragment-wrapped or not) is the caption and never lands in the plate; then the caption
          // is every <Text>, the plate everything else.
          const flat = flatten(content);
          const parts = isTextOnly(flat) ? [<Text key="caption">{flat}</Text>] : flat;
          const isCaption = (p: React.ReactNode) => isValidElement(p) && p.type === Text;
          // One image as the whole plate (an illustrated shortcut): it fills the round plate, which
          // clips it, instead of sitting in the middle as an icon does.
          const plate = parts.filter((p) => !isCaption(p));
          const isMediaPlate = plate.length === 1 && isValidElement(plate[0]) && plate[0].type === "img";
          return (
            <>
              <span className="sd-button__plate" data-media={isMediaPlate || undefined}>
                {renderProps.isPending ? (
                  <Spinner className="sd-button__spinner" tone="current" isDecorative size={roleSize(size)} />
                ) : (
                  <span className="sd-button__icon">
                    {isMediaPlate
                      ? cloneElement(plate[0] as React.ReactElement<{ className?: string }>, { className: "sd-button__media" })
                      : plate}
                  </span>
                )}
              </span>
              <span className="sd-button__label">
                <Provider values={[[TextContext, { className: "sd-button__text" }]]}>
                  {parts.filter(isCaption)}
                </Provider>
              </span>
            </>
          );
        }
        return (
          <>
            {/* isPending: react-aria blocks press and adds [data-pending]. Reuse the shared Spinner
              — tone="current" (inherits the button foreground, retaining contrast over a colored
              fill) + isDecorative (the button already announces its pending state, preventing a
              duplicate AT announcement). Hide the label while preserving its space to prevent
              width changes. */}
            {renderProps.isPending && (
              <Spinner
                className="sd-button__spinner"
                tone="current"
                isDecorative
                size={roleSize(size)}
              />
            )}
            <span
              className="sd-button__label"
              data-pending={renderProps.isPending || undefined}
            >
              {/* Text slot — React Aria's standard composition mechanism. Nineteen RAC components
                (ListBox · Menu · Toast · every field …) attach slots to child text with
                `Provider values={[[TextContext, …]]}`, and we are already a consumer
                (`<Text slot="description">`). React Spectrum's Button, from the react-aria family
                of design systems, uses the same API —
                `<Button><Bell /><Text>Icon + Label</Text></Button>`, with no icon prop.

                This box adds 4 on the left and right, restoring **to the text only** the amount
                removed by reducing the container padding one step: an icon reaches the edge of
                its own box but text does not, so equal padding makes the icon side look farther
                away. The icon remains a sibling outside this box, so the correction does not push
                the icon too — wrapping all of children would return the removed amount on the icon
                side as well and cancel the correction (confirmed by measurement).

                If children is **text only**, wrap all of it in one `<Text>` here. Checking only
                strings is insufficient — JSX passes `<Button>Items: {count}</Button>` as the array
                `["Items: ", count]` (Spectrum's `typeof === "string"` check misses this), so the
                correction disappears entirely and makes it 8 narrower than a string button with
                the same label. Therefore, test whether it consists only of strings/numbers and
                wrap it in a single `<Text>` (wrapping each fragment would insert 4+4 between
                fragments). If elements are mixed in, do not wrap — that element may be the icon,
                and the correction must not reach the icon. In that case the consumer wraps the
                label in `<Text>`. icon-only children is an element and is therefore not wrapped,
                so `__text` itself is not created. */}
              <Provider
                values={[[TextContext, { className: "sd-button__text" }]]}
              >
                {isTextOnly(content) ? <Text>{content}</Text> : content}
              </Provider>
            </span>
          </>
        );
      }}
    </AriaButton>
  );
}

/* Button.css — .sd-button
   규칙: (1) sd- 프리픽스  (2) 단일 클래스 + 낮은 명시도, 하위결합자 금지
        (3) variant·state 는 같은 요소의 data-* 속성으로  (4) Cmp 토큰만 참조
   상태 data-* 는 react-aria-components 가 렌더링 시 자동으로 붙여준다. */
.sd-button {
  --sd-button-radius-current: var(--sd-button-radius-medium);
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: var(--sd-button-border-width) solid transparent;
  border-radius: var(--sd-button-radius-current);
  corner-shape: superellipse(var(--sd-radius-curve));
  cursor: pointer;
  user-select: none;
  /* LinkButton draws this look on an <a>, which the browser underlines; a <button> never is. */
  text-decoration: none;
  transition:
    background-color var(--sd-duration-moderate) var(--sd-easing-standard),
    border-color var(--sd-duration-moderate) var(--sd-easing-standard),
    transform var(--sd-duration-fast) var(--sd-easing-standard);
  outline: none;
  /* Relays the vertical presentation's `__plate` reads (§6 rule 5): the variant's border and
     backdrop, and the state layer and focus ring, which the horizontal root reads too. */
  --sd-button-border-current: transparent;
  --sd-button-backdrop-current: none;
  --sd-button-state-layer-current: transparent;
  /* The wash each state lays over this variant's fill: the surface wash, or on a solid fill the one
     named for its ink, which goes away from that ink (contrast-contract.mjs § the state layer). */
  --sd-button-state-hover-current: var(--sd-state-hover);
  --sd-button-state-pressed-current: var(--sd-state-pressed);
  --sd-button-ring-current: none;
  --sd-button-ring-outline-current: none;
}

/* size — height and corner. font-size comes from the size-matched type role class
   (sd-type-label-<size>) on the root (see Button.tsx); a text button's inline glyph is 1em
   of that label size. Icon-only buttons override font-size to the icon scale below. */
.sd-button[data-size="x-small"] {
  --sd-button-radius-current: var(--sd-button-radius-x-small);
  --sd-button-height-current: var(--sd-button-height-x-small);
  --sd-button-icon-size-current: var(--sd-button-icon-size-x-small);
}
.sd-button[data-size="small"] {
  --sd-button-radius-current: var(--sd-button-radius-small);
  --sd-button-height-current: var(--sd-button-height-small);
  --sd-button-icon-size-current: var(--sd-button-icon-size-small);
}
.sd-button[data-size="medium"] {
  --sd-button-radius-current: var(--sd-button-radius-medium);
  --sd-button-height-current: var(--sd-button-height-medium);
  --sd-button-icon-size-current: var(--sd-button-icon-size-medium);
}
.sd-button[data-size="large"] {
  --sd-button-radius-current: var(--sd-button-radius-large);
  --sd-button-height-current: var(--sd-button-height-large);
  --sd-button-icon-size-current: var(--sd-button-icon-size-large);
}
.sd-button[data-size="x-large"] {
  --sd-button-radius-current: var(--sd-button-radius-x-large);
  --sd-button-height-current: var(--sd-button-height-x-large);
  --sd-button-icon-size-current: var(--sd-button-icon-size-x-large);
}
.sd-button:not([data-orientation="vertical"])[data-size="x-small"] {
  height: var(--sd-button-height-x-small);
}
.sd-button:not([data-orientation="vertical"])[data-size="small"] {
  height: var(--sd-button-height-small);
}
.sd-button:not([data-orientation="vertical"])[data-size="medium"] {
  height: var(--sd-button-height-medium);
}
.sd-button:not([data-orientation="vertical"])[data-size="large"] {
  height: var(--sd-button-height-large);
}
.sd-button:not([data-orientation="vertical"])[data-size="x-large"] {
  height: var(--sd-button-height-x-large);
}

/* 인라인 패딩 — 텍스트 버튼 전용. 아이콘 전용은 정사각이라 인라인 패딩을 아예 받지
   않는다: :not([data-icon-only]) 로 가드해 두 규칙군이 서로소인 요소를 겨냥하므로,
   둘 사이의 소스 순서/명시도에 의존하지 않는다(재정렬해도 안전). 같은 요소 위의
   속성 셀렉터라 하위결합자 규칙도 지킨다(cf. Tree.css). */
.sd-button:not([data-icon-only]):not([data-media-only]):not([data-orientation="vertical"])[data-size="x-small"] {
  padding-inline: var(--sd-button-padding-inline-x-small);
}
.sd-button:not([data-icon-only]):not([data-media-only]):not([data-orientation="vertical"])[data-size="small"] {
  padding-inline: var(--sd-button-padding-inline-small);
}
.sd-button:not([data-icon-only]):not([data-media-only]):not([data-orientation="vertical"])[data-size="medium"] {
  padding-inline: var(--sd-button-padding-inline-medium);
}
.sd-button:not([data-icon-only]):not([data-media-only]):not([data-orientation="vertical"])[data-size="large"] {
  padding-inline: var(--sd-button-padding-inline-large);
}
.sd-button:not([data-icon-only]):not([data-media-only]):not([data-orientation="vertical"])[data-size="x-large"] {
  padding-inline: var(--sd-button-padding-inline-x-large);
}
/* ghost: one step tighter on the inline axis. A ghost has no fill or border, so the padding is
   the only thing separating its label from a neighbour — matching the filled variants makes a
   row of ghosts read as over-spaced. Same `:not([data-icon-only])` guard as above (icon-only is
   already 0), and one extra attribute over those rules so it wins regardless of source order. */
.sd-button:not([data-icon-only]):not([data-media-only]):not([data-orientation="vertical"])[data-variant="ghost"][data-size="x-small"] {
  padding-inline: var(--sd-button-padding-inline-ghost-x-small);
}
.sd-button:not([data-icon-only]):not([data-media-only]):not([data-orientation="vertical"])[data-variant="ghost"][data-size="small"] {
  padding-inline: var(--sd-button-padding-inline-ghost-small);
}
.sd-button:not([data-icon-only]):not([data-media-only]):not([data-orientation="vertical"])[data-variant="ghost"][data-size="medium"] {
  padding-inline: var(--sd-button-padding-inline-ghost-medium);
}
.sd-button:not([data-icon-only]):not([data-media-only]):not([data-orientation="vertical"])[data-variant="ghost"][data-size="large"] {
  padding-inline: var(--sd-button-padding-inline-ghost-large);
}
.sd-button:not([data-icon-only]):not([data-media-only]):not([data-orientation="vertical"])[data-variant="ghost"][data-size="x-large"] {
  padding-inline: var(--sd-button-padding-inline-ghost-x-large);
}

/* icon-only: 정사각. 위 size 규칙의 height 를 그대로 쓰고 폭만 맞춘다(aspect-ratio:1
   + border-box 로 width 가 height 를 따라간다). 인라인 패딩은 명시적으로 0 으로 둔다
   — 텍스트용 size 패딩은 :not([data-icon-only]) 로 서로소라 여기에 닿지 않으므로
   이 0 은 어떤 규칙과도 충돌하지 않고(순서 무관) 브라우저 기본 <button> 패딩만
   덮는다. 글리프 크기: 아이콘 전용은 라벨 1em 이 아니라 아이콘 스케일을 따르되 한 단계 위를
   쓴다 — 16/20/24(icon medium/large/x-large, 아래 [data-size] 규칙). 곁에 글자가 없어 글리프
   혼자 버튼을 채워야 하므로, 텍스트와 함께 쓰일 때의 12/16/20 보다 한 칸 크다. */
.sd-button[data-icon-only] {
  padding-inline: 0;
  aspect-ratio: 1;
}

/* media-only: 정사각 + 자기 radius 로 클리핑. icon-only 와 같은 메커니즘(height + aspect-ratio)이지만
   글리프 규칙은 받지 않는다 — 미디어는 자기 치수를 가져오므로 font-size 로 크기를 정할 대상이 없다.
   `overflow: hidden` 이 여기 있는 이유: 클리핑되는 모양은 이 버튼의 radius 이고, radius 를 소유한
   쪽이 클리핑도 소유해야 한다. 밖에서 씌우면 Block 이 Component 의 박스를 다시 칠하는 것이 되고
   그것이 block-contract.md §3 이 금지하는 것이다. box-shadow 포커스 링은 overflow 로 잘리지 않는다. */
.sd-button[data-media-only] {
  padding-inline: 0;
  aspect-ratio: 1;
  overflow: hidden;
  /* 미디어는 네모로 읽혀야 한다 — 같은 불변식을 checkbox/box/radius 에도 썼다: 컨트롤 박스의 코너는
     박스를 원으로 만드는 radius 의 절반까지만 쓴다. 정사각에서 원은 50% 이므로 상한은 25% 이고,
     퍼센트라 사이즈별 토큰이 필요 없다(박스 자신을 기준으로 풀린다). `min()` 이므로 이미 낮은
     브랜드에서는 --sd-button-radius-current 가 그대로 이긴다. isIconOnly 는 일부러 건드리지 않는다 —
     원형 아이콘 버튼은 이 브랜드의 의도된 룩이고, 잘려서 곤란한 콘텐츠도 없다. */
  border-radius: min(var(--sd-button-radius-current), 25%);
  corner-shape: superellipse(var(--sd-radius-curve));
}
/* shape="circle": the icon-only square rounded fully. The type allows it only with isIconOnly, so
   the box is always square here and `radius.full` clamps to a circle. One attribute, like the
   media-only cap above, and the two never meet on one element (the union forbids it). */
.sd-button[data-shape="circle"] {
  border-radius: var(--sd-button-radius-circle);
  corner-shape: round;
}
/* icon-only glyph one rung UP the icon scale (16/20/24), not the label 1em — a bare affordance
   icon carries the button alone, so it reads a step larger than the 12/16/20 an icon takes
   beside text. Overrides sd-type-label-<size> font-size (higher specificity), so the 1em glyph
   resolves to the icon size. */
.sd-button[data-icon-only][data-size="x-small"] {
  font-size: var(--sd-button-icon-size-x-small);
}
.sd-button[data-icon-only][data-size="small"] {
  font-size: var(--sd-button-icon-size-small);
}
.sd-button[data-icon-only][data-size="medium"] {
  font-size: var(--sd-button-icon-size-medium);
}
.sd-button[data-icon-only][data-size="large"] {
  font-size: var(--sd-button-icon-size-large);
}
.sd-button[data-icon-only][data-size="x-large"] {
  font-size: var(--sd-button-icon-size-x-large);
}

/* variant: primary — solid fill, rest state only. Hover/pressed feedback comes
   from the global state-layer overlay below (::after), not per-variant shades. */
.sd-button[data-variant="primary"] {
  background: var(--sd-button-background-primary);
  color: var(--sd-button-foreground-primary);
  --sd-button-background-current: var(--sd-button-background-primary);
  --sd-button-foreground-current: var(--sd-button-foreground-primary);
  --sd-button-state-hover-current: var(--sd-state-hover-on-color);
  --sd-button-state-pressed-current: var(--sd-state-pressed-on-color);
}
/* secondary: the ladder's non-primary rung. Fill and edge are the BRAND's (ADR-0045): a neutral
   fill with a transparent edge where the brand fills the rung, a transparent fill with the default
   edge where it outlines it. The base rule already reserves the border box, so neither look moves
   the layout. */
.sd-button[data-variant="secondary"] {
  background: var(--sd-button-background-secondary);
  color: var(--sd-button-foreground-secondary);
  border-color: var(--sd-button-border-secondary);
  --sd-button-background-current: var(--sd-button-background-secondary);
  --sd-button-foreground-current: var(--sd-button-foreground-secondary);
  --sd-button-border-current: var(--sd-button-border-secondary);
  --sd-button-state-hover-current: var(--sd-state-hover-secondary);
  --sd-button-state-pressed-current: var(--sd-state-pressed-secondary);
}
/* outline: transparent fill + border, the MEDIA look (prop-usage-contract § media): an edge over a
   photo or video; no border on ghost/primary/destructive, and secondary's is the brand's. Frosted
   glass: the transparent fill lets backdrop-filter blur whatever sits behind the button. A
   no-op over a solid surface; over content/media it frosts the backdrop and lifts label
   legibility. -webkit- prefix for Safari. */
.sd-button[data-variant="outline"] {
  background: var(--sd-button-background-outline);
  color: var(--sd-button-foreground-outline);
  border-color: var(--sd-button-border-outline);
  -webkit-backdrop-filter: blur(var(--sd-button-backdrop-blur));
  backdrop-filter: blur(var(--sd-button-backdrop-blur));
  --sd-button-background-current: var(--sd-button-background-outline);
  --sd-button-foreground-current: var(--sd-button-foreground-outline);
  --sd-button-border-current: var(--sd-button-border-outline);
  --sd-button-backdrop-current: blur(var(--sd-button-backdrop-blur));
}
/* destructive: solid destructive fill (like primary, no border). ghost: transparent, no
   border — hover/pressed come from the global ::after state-layer, same as every button. */
.sd-button[data-variant="destructive"] {
  background: var(--sd-button-background-destructive);
  color: var(--sd-button-foreground-destructive);
  --sd-button-background-current: var(--sd-button-background-destructive);
  --sd-button-foreground-current: var(--sd-button-foreground-destructive);
  --sd-button-state-hover-current: var(--sd-state-hover-on-destructive);
  --sd-button-state-pressed-current: var(--sd-state-pressed-on-destructive);
}
.sd-button[data-variant="ghost"] {
  background: var(--sd-button-background-ghost);
  color: var(--sd-button-foreground-ghost);
  --sd-button-background-current: var(--sd-button-background-ghost);
  --sd-button-foreground-current: var(--sd-button-foreground-ghost);
}
/* surface: the page's own surface and ink, solid and borderless like secondary, for a Button on a
   canvas that is not a surface (a tinted row, a grey canvas, a wallpaper). Hover/pressed come from
   the shared ::after state-layer like every variant. */
.sd-button[data-variant="surface"] {
  background: var(--sd-button-background-surface);
  color: var(--sd-button-foreground-surface);
  --sd-button-background-current: var(--sd-button-background-surface);
  --sd-button-foreground-current: var(--sd-button-foreground-surface);
}
/* tonal: the brand's tint with the brand's ink, medium emphasis. strong: the neutral solid with its
   own on-colour ink, co-equal with primary but not the brand's call. Both borderless; hover and
   pressed come from the shared ::after state-layer like every variant. */
.sd-button[data-variant="tonal"] {
  background: var(--sd-button-background-tonal);
  color: var(--sd-button-foreground-tonal);
  --sd-button-background-current: var(--sd-button-background-tonal);
  --sd-button-foreground-current: var(--sd-button-foreground-tonal);
  --sd-button-state-hover-current: var(--sd-state-hover-brand-subtle);
  --sd-button-state-pressed-current: var(--sd-state-pressed-brand-subtle);
}
.sd-button[data-variant="strong"] {
  background: var(--sd-button-background-strong);
  color: var(--sd-button-foreground-strong);
  --sd-button-background-current: var(--sd-button-background-strong);
  --sd-button-foreground-current: var(--sd-button-foreground-strong);
  --sd-button-state-hover-current: var(--sd-state-hover-on-neutral-strong);
  --sd-button-state-pressed-current: var(--sd-state-pressed-on-neutral-strong);
}
/* provider: a third party's own fill and ink, which the caller sets inline on the element
   (Button.tsx) and which hold in every theme and brand, because they are the party's and not the
   theme's. The caller owns the pair's 4.5:1. The wash is primary's, the solid-fill one: no wash
   can be derived for a colour the system never sees. */
.sd-button[data-variant="provider"] {
  background: var(--sd-button-provider-background);
  color: var(--sd-button-provider-foreground);
  --sd-button-background-current: var(--sd-button-provider-background);
  --sd-button-foreground-current: var(--sd-button-provider-foreground);
  --sd-button-state-hover-current: var(--sd-state-hover-on-color);
  --sd-button-state-pressed-current: var(--sd-state-pressed-on-color);
}

/* Each variant paints the root directly and also hands its look to `__plate` through the relays;
   the vertical presentation below turns the root's paint off, one attribute more specific. */

/* Global interaction state-layer: one theme-aware alpha overlay renders hover/pressed
   over ANY fill (brand, transparent, …), replacing per-variant shade tokens. pointer-events
   none so React Aria press/hover pass through; content (label/spinner) sits above it. */
.sd-button::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  corner-shape: inherit;
  background: var(--sd-button-state-layer-current);
  pointer-events: none;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-button[data-hovered] {
  --sd-button-state-layer-current: var(--sd-button-state-hover-current);
}
.sd-button[data-pressed] {
  --sd-button-state-layer-current: var(--sd-button-state-pressed-current);
}

/* state (variant 무관 공통) */
.sd-button[data-pressed] {
  transform: scale(var(--sd-state-pressed-scale));
}
.sd-button[data-focus-visible] {
  --sd-button-ring-current: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  --sd-button-ring-outline-current: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-button:not([data-orientation="vertical"]) {
  box-shadow: var(--sd-button-ring-current);
  outline: var(--sd-button-ring-outline-current);
}
.sd-button[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}
/* isPending: react-aria emits [data-pending] and suppresses press. The spinner
   below carries the state, so the button keeps full opacity (no dim) — only the
   cursor changes. */
.sd-button[data-pending] {
  cursor: progress;
}

/* Content wrapper — holds the label/icon so the pending spinner can overlay it.
   gap lives here (moved off .sd-button) since this is the flex row for content. */
/* 텍스트 상자 — 글자에만 붙는 좌우 4(§7: 박스 속성을 가진 텍스트 파트는 자기 요소를 갖는다,
   Accordion 의 `__title` 과 같은 구조). 컨테이너 패딩을 한 단계 줄인 만큼을 글자 쪽에서만
   되돌려, 상자에 담긴 아이콘과 맨 글자의 시각적 여백을 맞춘다. 아이콘은 이 상자의 형제라
   보정을 받지 않는다 — Button.tsx 의 TextContext 슬롯이 그 분리를 만든다.
   `__label` 의 flex 아이템이므로 블록으로 승격되고, 패딩은 줄바꿈된 라벨에도 온전히 걸린다. */
.sd-button__text {
  padding-inline: var(--sd-button-text-padding-inline);
}

.sd-button__label {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--sd-button-gap);
  /* above the ::after state-layer overlay */
  position: relative;
  z-index: 1;
}
/* While pending, keep the label's box (no width collapse) and hide it visually with
   opacity — NOT visibility:hidden, which would drop the label from the accessibility
   tree and leave the button with no accessible name (axe button-name / WCAG 4.1.2)
   while the spinner is aria-hidden. opacity:0 keeps the name for AT, hides it for
   sighted users. data-pending is stamped on the same element (no descendant combinator). */
.sd-button__label[data-pending] {
  opacity: 0;
}

/* Pending spinner = the shared Spinner component (tone=current, decorative). The Button owns
   only its overlay placement — centered over the hidden label; the spinner's look, size, and
   motion (incl. reduced-motion) live in Spinner. inset:0 + margin:auto centers the fixed-size
   spinner within the position:relative button. */
.sd-button__spinner {
  position: absolute;
  inset: 0;
  margin: auto;
  z-index: 1;
}

/* ── Vertical presentation: a round plate over a caption (orientation="vertical") ───────────────
   The root becomes a transparent column and the variant's look moves to `__plate`, which reads the
   relays each variant rule sets beside its own paint. The caption is the button's visible name, set in the
   ordinary text colour; the whole column is the press target. */
/* One attribute, like the variant rules it overrides, so it wins by source order (it comes after
   them) and every CSS-reading check still sees a single-attribute rule. */
.sd-button[data-orientation="vertical"] {
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
  flex-direction: column;
  gap: var(--sd-button-vertical-gap);
  height: auto;
  padding: 0;
  border-width: 0;
  border-color: transparent;
  background: transparent;
  color: var(--sd-button-vertical-foreground);
  text-align: center;
}
.sd-button[data-orientation="vertical"]::after {
  content: none;
}
.sd-button__plate {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  inline-size: var(--sd-button-height-current);
  block-size: var(--sd-button-height-current);
  border: var(--sd-button-border-width) solid var(--sd-button-border-current);
  border-radius: var(--sd-button-plate-radius);
  corner-shape: round;
  background: var(--sd-button-background-current);
  color: var(--sd-button-foreground-current);
  -webkit-backdrop-filter: var(--sd-button-backdrop-current);
  backdrop-filter: var(--sd-button-backdrop-current);
  font-size: var(--sd-button-icon-size-current);
  box-shadow: var(--sd-button-ring-current);
  outline: var(--sd-button-ring-outline-current);
  transition:
    background-color var(--sd-duration-moderate) var(--sd-easing-standard),
    border-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-button__plate::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  corner-shape: inherit;
  background: var(--sd-button-state-layer-current);
  pointer-events: none;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}

/* An image plate: the image is the whole plate, clipped to its round edge, and the state layer still
   washes over it. */
.sd-button__plate[data-media] {
  inline-size: var(--sd-button-plate-media-size);
  block-size: var(--sd-button-plate-media-size);
  overflow: hidden;
  --sd-button-plate-content-size-current: 100%;
}
.sd-button__media {
  display: block;
  inline-size: 100%;
  block-size: 100%;
  object-fit: cover;
}

/* The plate's content, above its state layer like `__label` is above the root's. */
.sd-button__icon {
  position: relative;
  z-index: 1;
  display: inline-flex;
  /* `auto` for a glyph; an image plate sets 100% through the relay above (§6 rule 5). */
  inline-size: var(--sd-button-plate-content-size-current, auto);
  block-size: var(--sd-button-plate-content-size-current, auto);
}

/* The press scale is movement, so it goes; the colour fades stay. */
@media (prefers-reduced-motion: reduce) {
  .sd-button[data-pressed] {
    transform: none;
  }
}
